 if(argc!=3)throw std::runtime_error("project and fresh fixture required");const std::filesystem::path project=argv[1],root=argv[2];if(std::filesystem::exists(root)||root.parent_path()!=std::filesystem::path("/private/tmp"))throw std::runtime_error("fresh private fixture required");std::filesystem::create_directory(root);std::filesystem::permissions(root,std::filesystem::perms::owner_all,std::filesystem::perm_options::replace);juce::ScopedJuceInitialiser_GUI gui;
 storage::StoreOptions options;options.path=root/"profile.sqlite";options.create=true;options.createdUtc="2026-10-25T00:00:00Z";options.preferenceValidator=desktop::presentation::composedPreferenceValidator;auto store=std::make_unique<storage::ProfileStore>(options);const auto profile=store->readProfileIdentity(storage::newUuid()).get().data.object().at("profile_id").string();
